function hasControlCharacter(text: string): boolean {
  return /\p{Cc}/u.test(text);
}

function cleanThenCheck(raw: string): string {
  const clean = raw.replace(/\s+/g, " ").trim();
  return hasControlCharacter(clean) ? "control character" : "ok";
}

for (const raw of ["Buy milk", "Buy\tmilk\n", "Pay rent\u0007", "\u0000Book plumber"]) {
  console.log(JSON.stringify(raw), cleanThenCheck(raw));
}

