function titleKey(title: string): string {
  return title.normalize("NFKC").replace(/\s+/g, " ").trim().toLowerCase();
}

function findDuplicates(titles: string[]): string[] {
  const seen = new Set<string>();
  const duplicates: string[] = [];
  for (const title of titles) {
    const key = titleKey(title);
    if (seen.has(key)) duplicates.push(title);
    seen.add(key);
  }
  return duplicates;
}

console.log(findDuplicates(["Buy milk", "Walk the dog", " BUY  MILK", "Ｗａｌｋ the dog", "Water plants"]));

