type Step<T> = (value: T) => string[];

function compose<T>(steps: Step<T>[], stopOnFirst: boolean): (value: T) => string[] {
  return (value) => {
    const messages: string[] = [];
    for (const step of steps) {
      const found = step(value);
      messages.push(...found);
      if (stopOnFirst && found.length > 0) break;
    }
    return messages;
  };
}

const whole: Step<number> = (kobo) => (Number.isInteger(kobo) ? [] : ["whole kobo only"]);
const ussdCap: Step<number> = (kobo) => (kobo <= 2_000_000 ? [] : ["USSD limit is ₦20,000"]);

console.log(compose([whole, ussdCap], true)(4_500_000.5));
console.log(compose([whole, ussdCap], false)(4_500_000.5));

