function depthOf(value: unknown, limit: number): number {
  let deepest = 0;
  const stack: [unknown, number][] = [[value, 0]];
  while (stack.length > 0) {
    const [current, depth] = stack.pop()!;
    if (typeof current !== "object" || current === null) continue;
    const level = depth + 1;
    if (level > limit) return limit + 1;
    deepest = Math.max(deepest, level);
    for (const child of Object.values(current)) stack.push([child, level]);
  }
  return deepest;
}

console.log(depthOf("text", 10), depthOf([], 10), depthOf({ task: { tags: ["home"] } }, 10));
console.log(depthOf(JSON.parse("[".repeat(100000) + "]".repeat(100000)), 10));

