type Issue = { path: (string | number)[]; message: string };

function fieldErrors(issues: Issue[]): Record<string, string> {
  const errors: Record<string, string> = {};
  for (const issue of issues) {
    const field = issue.path.length > 0 ? String(issue.path[0]) : "(form)";
    if (!Object.hasOwn(errors, field)) errors[field] = issue.message;
  }
  return errors;
}

console.log(
  fieldErrors([
    { path: ["tags", 1], message: "Tag too long" },
    { path: ["tags", 2], message: "Tag has spaces" },
    { path: ["title"], message: "Title too short" },
    { path: [], message: "Send at least one field" },
    { path: ["constructor"], message: "Unknown field" },
  ]),
);
